output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides and the horizontal clearance is only one cell.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "An agent must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": "MOVE",
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cartless_only_near_cart_or_single_file",
    "text": "Moving without a cart is allowed only at the entrance cart area, at a narrow aisle mouth, or inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartBayApproach": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "allowedCartlessZone": {
          "or": [
            "singleFileAisle",
            "aisleMouth",
            "cartBayApproach"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessZone"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "Whenever an agent parks the cart at a narrow aisle mouth, they are obliged to reclaim it before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkAtAisleMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "aisleMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveAtAisleMouth": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "aisleMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkAtAisleMouth",
      "discharge": "retrieveAtAisleMouth"
    }
  },
  {
    "id": "park_only_at_approved_aisle_mouths",
    "text": "Carts may only be parked at the wide staging cells immediately outside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "approvedCartParkingSpot": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "approvedCartParkingSpot"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions from open cart-accessible aisles must be performed with the cart, while single-file shelf aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfServicePoint",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_backtracking_from_north_shelf_bottleneck",
    "text": "At cart-accessible north-facing shelf bottlenecks, cart users must not turn back north or west and should continue south or east instead.",
    "abstraction": {
      "state_properties": {
        "northShelfBottleneck": {
          "and": [
            "shelfN",
            {
              "le": [
                "freeWidthV",
                2
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "northShelfBottleneck",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "return_to_mouth_after_single_file_pick",
    "text": "After interacting with an item shelf inside a single-file aisle, the agent is obliged to return cartless to the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAtAisleMouth": {
          "and": [
            "aisleMouth",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfInteraction",
      "discharge": "cartlessAtAisleMouth"
    }
  }
]
